for ordering in permutations(classes):
    rank = {name: i for i, name in enumerate(ordering)}
    if not all(rank[a] < rank[b] for a, b in constraints):
        continue
    correct = {
        letter
        for letter, sequence in option_classes.items()
        if all(rank[a] < rank[b] for a, b in zip(sequence, sequence[1:]))
    }
    results.append(correct)

