print("Orders in which K is correct:", sum(not correct for correct in results))

submitted = "K"
if submitted == "K" and all(correct for correct in results):
    print("CHECK FAIL: J is necessarily correctly ordered, so K is false.")
elif submitted == "K" and all(not correct for correct in results):
    print("CHECK PASS")
