import json
from itertools import combinations

facts = {
    "ant_deals_with_stork",
    "dragon_photographs_fish",
    "mannikin_hides_cards_from_liger",
    "mouse_in_Nigeria",
    "worm_neglects_chihuahua",
    "not_crow_surrenders_to_wolf",
    "not_dalmatian_trades_with_stork",
}

# Nigeria is in Africa.
if "mouse_in_Nigeria" in facts:
    facts.add("mouse_in_Africa")

money = {"stork": 98}
if all(animal in money for animal in ("stork", "walrus")):
    if money["stork"] > money["walrus"]:
        facts.add("stork_richer_than_walrus")

# Each signed conclusion has its explicit opposite.
rules = {
    1: ({"ant_deals_with_stork", "not_dalmatian_trades_with_stork"},
        "stork_builds_plant"),
    2: ({"stork_builds_plant"}, "not_mouse_shouts"),
    3: ({"stork_richer_than_walrus"}, "not_stork_builds_plant"),
    4: ({"mouse_in_Africa"}, "mouse_smiles"),
    5: ({"mouse_hugs_dinosaur", "mouse_smiles"}, "mouse_shouts"),
    6: ({"llama_has_instrument"}, "llama_calls"),
    7: ({"mouse_works_in_agriculture"}, "not_mouse_smiles"),
    8: ({"dragon_photographs_fish"}, "not_llama_calls"),
}
preferences = {(3, 1), (5, 2), (6, 8), (7, 4)}

def opposite(atom):
    return atom[4:] if atom.startswith("not_") else "not_" + atom

# Exhaustively enumerate self-consistent sets of undefeated rule applications.
models = []
ids = tuple(rules)
for size in range(len(ids) + 1):
    for subset in combinations(ids, size):
        accepted = set(subset)
        state = facts | {rules[i][1] for i in accepted}
        applicable = {
            i for i, (premises, conclusion) in rules.items()
            if premises <= state
        }
        undefeated = {
            i for i in applicable
            if not any(
                (j, i) in preferences
                and rules[j][1] == opposite(rules[i][1])
                for j in applicable
            )
        }
        if accepted != undefeated:
            continue

        # Require forward-grounded support rather than circular assumptions.
        grounded = set(facts)
        while True:
            expanded = grounded | {
                rules[i][1] for i in accepted
                if rules[i][0] <= grounded
            }
            if expanded == grounded:
                break
            grounded = expanded
        if grounded != state:
            continue
        models.append((state, applicable, accepted))

answers = set()
for state, _, _ in models:
    positive = "mouse_shouts" in state
    negative = "not_mouse_shouts" in state
    if positive and negative:
        answers.add("UNSUPPORTED")
    elif positive:
        answers.add("proved")
    elif negative:
        answers.add("disproved")
    else:
        answers.add("unknown")

if not models or len(answers) != 1 or "UNSUPPORTED" in answers:
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": answers.pop(),
        "evidence": {
            "models": len(models),
            "accepted_rules": sorted(models[0][2]),
            "mouse_shouts": "mouse_shouts" in models[0][0],
            "mouse_does_not_shout": "not_mouse_shouts" in models[0][0],
            "derivation": [
                "Rule1 derives stork_builds_plant.",
                "Rule2 derives not_mouse_shouts.",
                "Rule3 lacks a known walrus money amount.",
                "Rule5 lacks mouse_hugs_dinosaur."
            ]
        }
    }, separators=(",", ":")))
