import itertools
import json

bikes = ("F", "G", "H", "J")
valid = []

for day1 in itertools.permutations(bikes):
    for day2 in itertools.permutations(bikes):
        if any(day1[i] == day2[i] for i in range(4)):
            continue
        if "F" in (day1[0], day2[0]):
            continue
        if "J" in (day1[3], day2[3]):
            continue
        if "H" not in (day1[2], day2[2]):
            continue
        if day1[3] != day2[1]:
            continue
        if day1[2] != "J":
            continue
        valid.append((day1, day2))

tests = {
    "A": lambda a, b: b[0] == "G",
    "B": lambda a, b: a[1] == "H",
    "C": lambda a, b: b[3] == "H",
    "D": lambda a, b: "J" in (a[1], b[1]),
    "E": lambda a, b: "G" in (a[2], b[2]),
}
counts = {
    label: sum(test(a, b) for a, b in valid)
    for label, test in tests.items()
}
possible = [label for label, count in counts.items() if count]
answer = possible[0] if len(possible) == 1 else "UNSUPPORTED"

evidence = {
    "valid_schedules": len(valid),
    "option_counts": counts,
    "rider_order": ["Reynaldo", "Seamus", "Theresa", "Yuki"],
}
if answer != "UNSUPPORTED":
    a, b = next((a, b) for a, b in valid if tests[answer](a, b))
    evidence["witness"] = {"day1": a, "day2": b}

print(json.dumps({"final_answer": answer, "evidence": evidence},
                 separators=(",", ":")))
