import json
from fractions import Fraction as F

# Exact arithmetic in Q(sqrt(39)), represented by (a, b).
D = 39

def add(u, v):
    return (u[0] + v[0], u[1] + v[1])

def neg(u):
    return (-u[0], -u[1])

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    a, b = u
    c, d = v
    return (a*c + D*b*d, a*d + b*c)

def div(u, v):
    c, d = v
    norm = c*c - D*d*d
    if not norm:
        raise ArithmeticError("Zero denominator")
    return mul(u, (c / norm, -d / norm))

def scalar(n):
    return (F(n), F(0))

def sign(u):
    a, b = u
    if b == 0:
        return (a > 0) - (a < 0)
    if a == 0:
        return (b > 0) - (b < 0)
    if a > 0 and b > 0:
        return 1
    if a < 0 and b < 0:
        return -1
    comparison = a*a - D*b*b
    return ((comparison > 0) - (comparison < 0)) * (1 if a > 0 else -1)

def fmt(u):
    a, b = u
    if b == 0:
        return str(a)
    if a == 0:
        return f"{b}*sqrt({D})"
    return f"{a} {'+' if b > 0 else '-'} {abs(b)}*sqrt({D})"

def objective(values):
    result = scalar(0)
    for i, j in ((0, 1), (0, 2), (1, 2)):
        u, v = values[i], values[j]
        result = add(result, div(add(mul(u, u), mul(v, v)), add(u, v)))
    return result

