import json
from math import isqrt, prod

n = 33146799
remaining = n
factors = []
d = 2

while d * d <= remaining:
    exponent = 0
    while remaining % d == 0:
        remaining //= d
        exponent += 1
    if exponent:
        factors.append((d, exponent))
    d = 3 if d == 2 else d + 2

if remaining > 1:
    factors.append((remaining, 1))

def is_prime(p):
    return p >= 2 and all(p % d != 0 for d in range(2, isqrt(p) + 1))

reconstructed = prod(p ** e for p, e in factors)
if reconstructed != n or not all(is_prime(p) for p, _ in factors):
    print("UNSUPPORTED")
else:
    primes = ", ".join(str(p) for p, _ in factors)
    factorization = " × ".join(
        str(p) if e == 1 else f"{p}^{e}" for p, e in factors
    )
    print(json.dumps({
        "final_answer": f"Prime factors: {primes}. Factorization: {factorization}.",
        "evidence": {
            "prime_exponents": factors,
            "product": reconstructed,
            "primality_verified_by_exhaustive_trial_division": True
        }
    }, separators=(",", ":")))
