import itertools
import json

riders = ("Reynaldo", "Seamus", "Theresa", "Yuki")
bikes = ("F", "G", "H", "J")
valid = []

for first in itertools.permutations(bikes):
    day1 = dict(zip(riders, first))
    if day1["Theresa"] != "J":
        continue
    for second in itertools.permutations(bikes):
        day2 = dict(zip(riders, second))
        if any(day1[r] == day2[r] for r in riders):
            continue
        if "F" in (day1["Reynaldo"], day2["Reynaldo"]):
            continue
        if "J" in (day1["Yuki"], day2["Yuki"]):
            continue
        if "H" not in (day1["Theresa"], day2["Theresa"]):
            continue
        if day1["Yuki"] != day2["Seamus"]:
            continue
        valid.append((day1, day2))

tests = {
    "A": lambda a, b: b["Reynaldo"] == "G",
    "B": lambda a, b: a["Seamus"] == "H",
    "C": lambda a, b: b["Yuki"] == "H",
    "D": lambda a, b: "J" in (a["Seamus"], b["Seamus"]),
    "E": lambda a, b: "G" in (a["Theresa"], b["Theresa"]),
}

counts = {
    option: sum(test(a, b) for a, b in valid)
    for option, test in tests.items()
}
possible = [option for option, count in counts.items() if count]

if len(possible) != 1:
    print("UNSUPPORTED")
else:
    answer = possible[0]
    a, b = next((a, b) for a, b in valid if tests[answer](a, b))
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "valid_schedules": len(valid),
            "option_support_counts": counts,
            "witness": {"day1": a, "day2": b}
        }
    }, separators=(",", ":")))
