import math

n = 33146799
remaining = n
factors = []

divisor = 2
while divisor * divisor <= remaining:
    while remaining % divisor == 0:
        factors.append(divisor)
        remaining //= divisor
    divisor = 3 if divisor == 2 else divisor + 2

if remaining > 1:
    factors.append(remaining)

def is_prime(value):
    if value < 2:
        return False
    return all(value % d != 0 for d in range(2, math.isqrt(value) + 1))

distinct = sorted(set(factors))
if math.prod(factors) != n or not all(is_prime(p) for p in distinct):
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": ", ".join(map(str, distinct)),
        "evidence": {
            "factorization": factors,
            "product": math.prod(factors),
            "all_factors_prime": True
        }
    }, separators=(",", ":")))
