import json
from fractions import Fraction as F

# Exact arithmetic in Q(sqrt(39)); each value is a pair (a, b).
RAD = 39

def value(a=0, b=0):
    return F(a), F(b)

def add(u, v):
    return u[0] + v[0], u[1] + v[1]

def neg(u):
    return -u[0], -u[1]

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    a, b = u
    c, d = v
    return a*c + RAD*b*d, a*d + b*c

def div(u, v):
    c, d = v
    norm = c*c - RAD*d*d
    if not norm:
        raise ArithmeticError("Zero denominator")
    return mul(u, (c / norm, -d / norm))

def sign(u):
    a, b = u
    if not b:
        return (a > 0) - (a < 0)
    if not a:
        return (b > 0) - (b < 0)
    if (a > 0) == (b > 0):
        return 1 if a > 0 else -1
    comparison = a*a - RAD*b*b
    if not comparison:
        return 0
    return ((a > 0) - (a < 0)) if comparison > 0 else ((b > 0) - (b < 0))

def text(u):
    a, b = u
    if not b:
        return str(a)
    radical = "sqrt(%d)" % RAD
    magnitude = abs(b)
    term = radical if magnitude == 1 else str(magnitude) + "*" + radical
    if not a:
        return ("-" if b < 0 else "") + term
    return str(a) + (" + " if b > 0 else " - ") + term

try:
    p, q = value(9), value(14)

    # With r=xyz, the original objective is
    # 2p - 2(q^2 + pr)/(pq-r).
    # Its derivative with respect to r is strictly negative.
    derivative_numerator = -2 * (9*9*14 + 14*14)
    assert derivative_numerator < 0

    # Maximize xyz on the compact nonnegative constraint set.
    # Boundary points have xyz=0. At an interior stationary point,
    # Lagrange multiplier equations force two variables to coincide.
    # Setting x=y=a gives 3a^2-18a+14=0.
    discriminant = 18**2 - 4*3*14
    assert discriminant == 4*RAD
    roots = [value(3, F(-1, 3)), value(3, F(1, 3))]
    feasible = []
    rejected = []

    for a in roots:
        b = sub(p, mul(value(2), a))
        assert add(mul(value(2), a), b) == p
        assert add(mul(a, a), mul(value(2), mul(a, b))) == q
        if sign(a) > 0 and sign(b) > 0:
            feasible.append((a, b, mul(mul(a, a), b)))
        else:
            rejected.append({"repeated": text(a), "third": text(b)})

    assert len(feasible) == 1
    a, b, r_max = feasible[0]
    assert sign(r_max) > 0

    denominator = sub(mul(p, q), r_max)
    assert sign(denominator) > 0
    answer = sub(
        mul(value(2), p),
        div(
            mul(value(2), add(mul(q, q), mul(p, r_max))),
            denominator
        )
    )

    # Independently evaluate the original three summands.
    original = value()
    for u, v in ((a, a), (a, b), (a, b)):
        original = add(original, div(add(mul(u, u), mul(v, v)), add(u, v)))
    assert original == answer

    print(json.dumps({
        "final_answer": text(answer),
        "evidence": {
            "objective_in_r": "(1876-36*r)/(126-r), r=xyz",
            "derivative": str(derivative_numerator) + "/(126-r)^2 < 0",
            "maximum_product": text(r_max),
            "attained_at": [text(a), text(a), text(b)],
            "rejected_stationary_branch": rejected,
            "global_argument": (
                "The nonnegative constraint set is compact. Boundary products "
                "are zero, whereas the displayed feasible product is positive. "
                "An interior product maximum has two equal coordinates by "
                "the Lagrange equations; only one such branch is positive."
            ),
            "original_expression_exactly_verified": True
        }
    }, separators=(",", ":")))
except Exception:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": "Exact computation could not settle the problem."},
                     separators=(",", ":")))
