import itertools
import json

# Distinguish an etiological cause from a trigger of symptoms.
# Observational counterexamples do not establish that a factor can never
# contribute to disease: individual susceptibility and other causes may vary.
models = list(itertools.product((False, True), repeat=3))
# Model fields: cold_is_root_cause, other_root_cause, cold_triggers_attacks.

def observation_possible(model, cold_exposure, arthritis):
    cold_root, other_root, _ = model
    return any(
        ((cold_root and cold_exposure and susceptible)
         or (other_root and other_exposure)) == arthritis
        for susceptible, other_exposure
        in itertools.product((False, True), repeat=2)
    )

constraints = {
    "A": lambda m: observation_possible(m, True, False),
    # B explicitly identifies different root causes and describes cold
    # exposure as precipitating an attack, rather than causing the disease.
    "B": lambda m: not m[0] and m[1] and m[2],
    "C": lambda m: observation_possible(m, True, False),
    "D": lambda m: observation_possible(m, False, True),
}

compatible = {
    option: [m for m in models if constraint(m)]
    for option, constraint in constraints.items()
}
cold_root_possible = {
    option: any(m[0] for m in remaining)
    for option, remaining in compatible.items()
}
refuting = [
    option for option in constraints
    if compatible[option] and not cold_root_possible[option]
]

if len(refuting) != 1:
    print(json.dumps({
        "final_answer": "UNSUPPORTED",
        "evidence": {"cold_root_possible": cold_root_possible}
    }, separators=(",", ":")))
else:
    print(json.dumps({
        "final_answer": refuting[0],
        "evidence": {
            "cold_root_possible": cold_root_possible,
            "distinction": "B separates root causes from triggers of attacks."
        }
    }, separators=(",", ":")))
