import json
from math import prod

original = 33146799
remaining = original
factors = []

divisor = 2
while divisor * divisor <= remaining:
    exponent = 0
    while remaining % divisor == 0:
        remaining //= divisor
        exponent += 1
    if exponent:
        factors.append((divisor, exponent))
    divisor = 3 if divisor == 2 else divisor + 2

if remaining > 1:
    factors.append((remaining, 1))

def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d = 3 if d == 2 else d + 2
    return True

product = prod(p ** exponent for p, exponent in factors)
if product != original or not all(is_prime(p) for p, _ in factors):
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": "Prime factors: " + ", ".join(str(p) for p, _ in factors),
        "evidence": {
            "factorization": [
                {"prime": p, "exponent": exponent}
                for p, exponent in factors
            ],
            "product": product,
            "primality_verified_by_trial_division": True
        }
    }, separators=(",", ":")))
