riders = ("Reynaldo", "Seamus", "Theresa", "Yuki")
bikes = ("F", "G", "H", "J")
valid = []

for day1 in itertools.permutations(bikes):
    for day2 in itertools.permutations(bikes):
        if any(day1[i] == day2[i] for i in range(4)):
            continue
        if "F" in (day1[0], day2[0]):
            continue
        if "J" in (day1[3], day2[3]):
            continue
        if "H" not in (day1[2], day2[2]):
            continue
        if day1[3] != day2[1]:
            continue
        if day1[2] != "J":
            continue
        valid.append((day1, day2))

tests = {
    "A": lambda d1, d2: d2[0] == "G",
    "B": lambda d1, d2: d1[1] == "H",
    "C": lambda d1, d2: d2[3] == "H",
    "D": lambda d1, d2: "J" in (d1[1], d2[1]),
    "E": lambda d1, d2: "G" in (d1[2], d2[2]),
}

matches = {
    label: [(d1, d2) for d1, d2 in valid if test(d1, d2)]
    for label, test in tests.items()
}
possible = [label for label, schedules in matches.items() if schedules]

