import json
from fractions import Fraction as F

s, q = F(9), F(14)
D = s * s - 3 * q

# Exact arithmetic in Q(sqrt(D)); a pair (a,b) denotes a+b*sqrt(D).
def scalar(a):
    return (F(a), F(0))

def add(u, v):
    return (u[0] + v[0], u[1] + v[1])

def neg(u):
    return (-u[0], -u[1])

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    return (u[0]*v[0] + D*u[1]*v[1],
            u[0]*v[1] + u[1]*v[0])

