import json

# The claim concerns the cause of Ms. Zhang's arthritis, not whether
# every lightly dressed person develops arthritis.
causes = ("wearing_less", "strain", "infection", "creation", "other")
medical_root_causes = {"strain", "infection", "creation"}

# A and C describe other people without arthritis; D describes other
# people with arthritis. None determines this patient's root cause.
# B explicitly identifies the root causes and distinguishes cold-weather
# exposure as an attack trigger.
def compatible(option, patient_cause):
    if option == "B":
        return patient_cause in medical_root_causes
    return True

survivors = {
    option: [cause for cause in causes if compatible(option, cause)]
    for option in ("A", "B", "C", "D")
}
claim_survives = {
    option: "wearing_less" in allowed
    for option, allowed in survivors.items()
}
contradicting_options = [
    option for option, survives in claim_survives.items() if not survives
]

answer = (
    contradicting_options[0]
    if len(contradicting_options) == 1
    else "UNSUPPORTED"
)
print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "claimed_root_cause": "wearing_less",
        "root_causes_stated_in_B": sorted(medical_root_causes),
        "claim_compatible_with_option": claim_survives,
        "distinction": "Triggering an arthritis attack is not causing arthritis."
    }
}, separators=(",", ":")))
