from itertools import product

# Each object/case has two Boolean properties X and Y.
# Every unary two-property model has one of the 16 possible sets of
# realized types below. Multiplicity cannot affect these formulas.
types = list(product((False, True), repeat=2))
models = [
    [types[i] for i in range(4) if mask & (1 << i)]
    for mask in range(16)
]

def some_x_not_y(model):
    return any(x and not y for x, y in model)

def some_y_not_x(model):
    return any(y and not x for x, y in model)

def not_all_x_are_y(model):
    return not all(not x or y for x, y in model)

options = {
    "Original": (
        "X=good, Y=cheap",
        some_x_not_y,
        some_y_not_x,
    ),
    "A": (
        "X=from Hunan, Y=likes pepper",
        some_x_not_y,
        some_y_not_x,
    ),
    "B": (
        "X=person, Y=selfish",
        some_x_not_y,
        not_all_x_are_y,
    ),
    "C": (
        "X=good motivation, Y=good result, on motive-result cases",
        some_x_not_y,
        some_y_not_x,
    ),
    "D": (
        "X=southerner, Y=Cantonese",
        some_x_not_y,
        some_y_not_x,
    ),
}

invalid = []
for label, (meaning, premise, conclusion) in options.items():
    counterexamples = [
        model for model in models
        if premise(model) and not conclusion(model)
    ]
    print(f"{label}: {'INVALID' if counterexamples else 'VALID'}; {meaning}")
    if counterexamples:
        witness = min(counterexamples, key=len)
        print("  Counterexample types (X, Y):", witness)
        print("  Premise =", premise(witness),
              "; conclusion =", conclusion(witness))
        if label != "Original":
            invalid.append(label)

print("Exact exhaustive type enumeration; not sampling.")
print("Invalid options:", ", ".join(invalid))
