import json

# Polynomial coefficients are in ascending powers of k.
def add(a, b):
    n = max(len(a), len(b))
    return tuple((a[i] if i < len(a) else 0) +
                 (b[i] if i < len(b) else 0) for i in range(n))

def subtract(a, b):
    return add(a, tuple(-x for x in b))

def evaluate(p, k):
    return sum(c * k**i for i, c in enumerate(p))

def formula(p):
    terms = []
    for i in reversed(range(len(p))):
        c = p[i]
        if c:
            power = "k" if i == 1 else f"k^{i}" if i else ""
            terms.append(power if c == 1 and power else
                         str(c) if not power else f"{c}*{power}")
    return "+".join(terms) or "0"

# Each pair n=2j-1,2j contributes (j-1)+j = 2j-1.
# Thus S_(2k) = 2*(k(k+1)/2)-k.
even = subtract((0, 1, 1), (0, 1, 0))
# The next term, floor((2k+1)/2), contributes k.
odd = add(even, (0, 1, 0))

lower_square = (0, 0, 1)  # k^2
upper_square = (1, 2, 1)  # (k+1)^2
lower_gap = subtract(odd, lower_square)
upper_gap = subtract(upper_square, odd)

# Nonnegative coefficients and a positive coefficient certify positivity
# for every integer k >= 1, without a finite-search cutoff.
def positive_for_k_ge_one(p):
    return all(c >= 0 for c in p) and any(c > 0 for c in p)

settled = (
    even == lower_square
    and positive_for_k_ge_one(lower_gap)
    and positive_for_k_ge_one(upper_gap)
)

if not settled:
    print(json.dumps({"final_answer": "UNSUPPORTED"}))
else:
    # Odd positive L have k >= 0. All k >= 1 are excluded by the bounds.
    exceptional = []
    value = evaluate(odd, 0)
    if value == 0:
        exceptional.append(2 * 0 + 1)

    parts = [f"L = {x}" for x in exceptional]
    parts.append("L is a positive even integer")
    print(json.dumps({
        "final_answer": " or ".join(parts) + ".",
        "evidence": {
            "S_(2k), k>=1": formula(even),
            "S_(2k+1), k>=0": formula(odd),
            "S_(2k+1)-k^2": formula(lower_gap),
            "(k+1)^2-S_(2k+1)": formula(upper_gap),
            "odd_exclusion": "Both gaps are positive for k>=1, so no square lies between the consecutive squares.",
            "exceptional_values": {
                str(L): sum(n // 2 for n in range(1, L + 1))
                for L in exceptional
            }
        }
    }, separators=(",", ":")))
