import json
import re

given = [
    ("tut", "tuot"),
    ("ura", "ura"),
    ("dunna", "duonna"),
    ("num", "nom"),
    ("nums", "noms"),
    ("insumma", "insomma"),
    ("numer", "nomer"),
    ("buglia", "buoglia"),
    ("discuors", "discuors"),
    ("puolpa", "puolpa"),
    ("angul", "angul"),
    ("fuorma", "fuorma"),
    ("flur", "flur"),
]

def tokenize(word):
    return re.findall(r"[aeiou]+|[^aeiou]+", word)

def is_vowel(token):
    return token[0] in "aeiou"

observations = []
for sursilvan, engadine in given:
    s, e = tokenize(sursilvan), tokenize(engadine)
    if len(s) != len(e):
        continue
    if any(
        is_vowel(a) != is_vowel(b) or (not is_vowel(a) and a != b)
        for a, b in zip(s, e)
    ):
        continue
    for i, token in enumerate(e):
        if is_vowel(token):
            right = e[i + 1] if i + 1 < len(e) else ""
            observations.append((token, right, s[i], sursilvan, engadine))

target = tokenize("cuort")
result = target[:]
evidence = []

for i, token in enumerate(target):
    if not is_vowel(token):
        continue
    right = target[i + 1] if i + 1 < len(target) else ""
    settled = False

    # Use the shortest following-consonant context giving a unanimous
    # correspondence among the supplied, fully observed word pairs.
    for width in range(len(right) + 1):
        matches = [
            row for row in observations
            if row[0] == token and row[1][:width] == right[:width]
        ]
        outputs = {row[2] for row in matches}
        if len(outputs) == 1:
            result[i] = outputs.pop()
            evidence.append({
                "engadine_vowel": token,
                "following_context": right[:width],
                "sursilvan_vowel": result[i],
                "support": [[row[3], row[4]] for row in matches],
            })
            settled = True
            break

    if not settled:
        print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": evidence}))
        break
else:
    print(json.dumps({
        "final_answer": "".join(result),
        "evidence": evidence
    }, separators=(",", ":")))
