from fractions import Fraction

total_lines = 1988
value = Fraction(1, 1)  # Innermost fraction: 1/1.
evidence = {
    "fraction_lines": total_lines,
    "innermost_value": str(value)
}

for level in range(2, total_lines + 1):
    # The innermost connecting sign is minus; all others are plus.
    denominator = 1 - value if level == 2 else 1 + value
    if denominator == 0:
        evidence.update({
            "undefined_at_fraction_line_from_bottom": level,
            "denominator": str(denominator),
            "reason": "Division by zero; the given expression defines no rational m/n."
        })
