import json
from fractions import Fraction

# Acidification of sodium bisulfite produces NaCl, SO2, and H2O.
atoms = {
    "NaHSO3": {"Na": 1, "H": 1, "S": 1, "O": 3},
    "HCl": {"H": 1, "Cl": 1},
    "NaCl": {"Na": 1, "Cl": 1},
    "SO2": {"S": 1, "O": 2},
    "H2O": {"H": 2, "O": 1},
}

bisulfite = Fraction(1)
water = Fraction(1)

# Derive amounts directly from elemental conservation.
sodium_chloride = bisulfite  # Sodium balance
sulfur_dioxide = bisulfite   # Sulfur balance
acid = 2 * water - bisulfite  # Hydrogen balance

reactants = {"NaHSO3": bisulfite, "HCl": acid}
products = {
    "NaCl": sodium_chloride,
    "SO2": sulfur_dioxide,
    "H2O": water,
}

elements = {element for formula in atoms.values() for element in formula}

def total(side, element):
    return sum(
        (amount * atoms[species].get(element, 0)
         for species, amount in side.items()),
        Fraction(0),
    )

valid = (
    all(amount >= 0 for amount in (*reactants.values(), *products.values()))
    and all(total(reactants, e) == total(products, e) for e in elements)
)

if not valid:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": {}}))
else:
    print(json.dumps({
        "final_answer": f"{acid} mole of Hydrochloric acid",
        "evidence": {
            "reactant_moles": {k: str(v) for k, v in reactants.items()},
            "product_moles": {k: str(v) for k, v in products.items()},
            "hydrogen_balance": f"1 + {acid} = 2",
            "all_elements_balanced": True
        }
    }, separators=(",", ":")))
