import json
from itertools import product

subjects = ("maths", "physics", "chemistry")
required = (6, 5, 5)
maximum_subjects_per_teacher = 4

# A teacher may belong to multiple subject groups; no disjointness is stated.
patterns = [
    p for p in product((0, 1), repeat=len(subjects))
    if 1 <= sum(p) <= maximum_subjects_per_teacher
]

reachable = {(0, 0, 0): ()}
solution = None

for teacher_count in range(sum(required) + 1):
    if required in reachable:
        solution = reachable[required]
        break
    next_reachable = {}
    for counts, assignment in reachable.items():
        for pattern in patterns:
            new_counts = tuple(a + b for a, b in zip(counts, pattern))
            if all(a <= b for a, b in zip(new_counts, required)):
                next_reachable.setdefault(new_counts, assignment + (pattern,))
    reachable = next_reachable

if solution is None:
    print(json.dumps({"final_answer": "UNSUPPORTED"}))
else:
    witness = {}
    for pattern in solution:
        label = "+".join(s for s, included in zip(subjects, pattern) if included)
        witness[label] = witness.get(label, 0) + 1

    print(json.dumps({
        "final_answer": str(len(solution)),
        "evidence": {
            "method": "exhaustive enumeration of overlapping subject memberships",
            "required_teacher_counts": dict(zip(subjects, required)),
            "lower_bound": max(required),
            "maximum_subjects_per_teacher": maximum_subjects_per_teacher,
            "witness": witness,
            "note": "Subject groups are not stated to be disjoint."
        }
    }, separators=(",", ":")))
