import json
from fractions import Fraction
from math import isqrt

magnitudes = (1, 2, 3)

# With common pairwise cosine t, the normalized Gram determinant is
# (1-t)^2(1+2t) = 1 - 3t^2 + 2t^3.
# Planarity requires determinant zero. The rational-root theorem
# exhausts its possible rational roots, which account for its degree.
roots = {
    Fraction(p, q)
    for p in (-1, 1)
    for q in (1, 2)
    if 1 - 3 * Fraction(p, q)**2 + 2 * Fraction(p, q)**3 == 0
}
assert sum(2 if t == 1 else 1 for t in roots) == 3

valid = sorted(t for t in roots if -1 <= t <= 1 and 1 - t*t >= 0)
base = sum(m*m for m in magnitudes)
pairs = sum(
    magnitudes[i] * magnitudes[j]
    for i in range(3)
    for j in range(i + 1, 3)
)

def exact_sqrt(value):
    assert value.denominator == 1 and value >= 0
    n = value.numerator
    r = isqrt(n)
    return str(r) if r*r == n else f"sqrt({n})"

evidence = [
    {
        "common_cosine": str(t),
        "squared_magnitude": str(Fraction(base) + 2*t*pairs),
        "magnitude": exact_sqrt(Fraction(base) + 2*t*pairs),
    }
    for t in valid
]

answers = [item["magnitude"] for item in evidence]
print(json.dumps({
    "final_answer": (
        answers[0] if len(answers) == 1
        else "Not uniquely determined: " + " or ".join(answers)
    ),
    "evidence": {
        "gram_determinant": "(1-t)^2(1+2t)",
        "cases": evidence,
        "note": "Zero equal angles are not excluded by the givens; excluding them leaves the negative-cosine case."
    }
}, separators=(",", ":")))
```

