import json
from fractions import Fraction

# Equation rewritten as sum(c * |a*x + b|) = 0.
terms = [(1, -24, 1), (1, -20, 1), (2, -44, -1)]
breakpoints = sorted({Fraction(-b, a) for a, b, _ in terms})
bounds = [None] + breakpoints + [None]

def text(value):
    if value.denominator == 1:
        return str(value.numerator)
    return f"{value.numerator}/{value.denominator}"

solutions = []
evidence = []

for lo, hi in zip(bounds, bounds[1:]):
    sample = hi - 1 if lo is None else lo + 1 if hi is None else (lo + hi) / 2
    slope = Fraction(0)
    intercept = Fraction(0)

    for a, b, coefficient in terms:
        sign = 1 if a * sample + b > 0 else -1
        slope += coefficient * sign * a
        intercept += coefficient * sign * b

    evidence.append({
        "bounds": [
            "-infinity" if lo is None else text(lo),
            "infinity" if hi is None else text(hi)
        ],
        "lhs_minus_rhs": {"slope": text(slope), "intercept": text(intercept)}
    })

    # The affine formula also holds at finite endpoints by continuity.
    if slope == 0:
        if intercept == 0:
            solutions.append((lo, hi))
    else:
        root = -intercept / slope
        if (lo is None or root >= lo) and (hi is None or root <= hi):
            solutions.append((root, root))

solutions.sort(key=lambda interval: (0, Fraction(0)) if interval[0] is None
               else (1, interval[0]))

merged = []
for lo, hi in solutions:
    if not merged:
        merged.append((lo, hi))
        continue
    previous_lo, previous_hi = merged[-1]
    if previous_hi is None or lo is None or lo <= previous_hi:
        merged[-1] = (
            previous_lo,
            None if previous_hi is None or hi is None else max(previous_hi, hi)
        )
    else:
        merged.append((lo, hi))

descriptions = []
for lo, hi in merged:
    if lo is None and hi is None:
        descriptions.append("all real x")
    elif lo is None:
        descriptions.append(f"x <= {text(hi)}")
    elif hi is None:
        descriptions.append(f"x >= {text(lo)}")
    elif lo == hi:
        descriptions.append(f"x = {text(lo)}")
    else:
        descriptions.append(f"{text(lo)} <= x <= {text(hi)}")

print(json.dumps({
    "final_answer": " or ".join(descriptions) if descriptions else "no real solutions",
    "evidence": evidence
}, separators=(",", ":")))
