# Exact polynomials in a, b, c, represented by exponent tuples.
def add(p, q):
    r = dict(p)
    for powers, coefficient in q.items():
        r[powers] = r.get(powers, 0) + coefficient
    return {powers: coefficient for powers, coefficient in r.items()
            if coefficient != 0}

def multiply(p, q):
    r = {}
    for u, x in p.items():
        for v, y in q.items():
            powers = tuple(i + j for i, j in zip(u, v))
            r[powers] = r.get(powers, 0) + x * y
    return {powers: coefficient for powers, coefficient in r.items()
            if coefficient != 0}

def subtract(p, q):
    return add(p, {powers: -coefficient
                   for powers, coefficient in q.items()})

def display(p):
    return [
        {"powers_abc": list(powers), "coefficient": coefficient}
        for powers, coefficient in sorted(p.items())
    ]

a = {(1, 0, 0): 1}
b = {(0, 1, 0): 1}
c = {(0, 0, 1): 1}
s = add(add(a, b), c)
abc = multiply(multiply(a, b), c)
pairs = add(add(multiply(a, b), multiply(b, c)), multiply(c, a))

