def add(p, q):
    r = dict(p)
    for powers, coefficient in q.items():
        r[powers] = r.get(powers, 0) + coefficient
    return {powers: coefficient for powers, coefficient in r.items()
            if coefficient != 0}

def multiply(p, q):
    r = {}
    for u, x in p.items():
        for v, y in q.items():
            powers = tuple(i + j for i, j in zip(u, v))
            r[powers] = r.get(powers, 0) + x * y
    return {powers: coefficient for powers, coefficient in r.items()
            if coefficient != 0}

def subtract(p, q):
    return add(p, {powers: -coefficient
                   for powers, coefficient in q.items()})

def display(p):
    return [
        {"powers_abc": list(powers), "coefficient": coefficient}
        for powers, coefficient in sorted(p.items())
    ]

a = {(1, 0, 0): 1}
b = {(0, 1, 0): 1}
c = {(0, 0, 1): 1}
s = add(add(a, b), c)
abc = multiply(multiply(a, b), c)
pairs = add(add(multiply(a, b), multiply(b, c)), multiply(c, a))

# Positivity gives the three arctangent arguments as ak, bk, ck,
# where k = sqrt((a+b+c)/(abc)) > 0.
#
# Expanding (1+iak)(1+ibk)(1+ick) yields
# real part D = 1-k^2(ab+bc+ca),
# imaginary part N = k[(a+b+c)-abc*k^2].
#
# Substitute k^2=s/abc exactly:
# N = (k/abc)*numerator, D = denominator/abc.
numerator = subtract(multiply(s, abc), multiply(abc, s))
denominator = subtract(abc, multiply(s, pairs))

# Every monomial is positive for positive a,b,c. Thus all-negative
# coefficients certify D<0 everywhere in the stated domain.
settled = (
    not numerator
    and bool(denominator)
    and all(coefficient < 0 for coefficient in denominator.values())
)

if settled:
    answer = Fraction(numerator.get((0, 0, 0), 0), 1)
    print(json.dumps({
        "final_answer": str(answer),
        "evidence": {
            "arguments": ["a*k", "b*k", "c*k"],
            "k_squared": "(a+b+c)/(a*b*c)",
            "scaled_tangent_numerator": display(numerator),
            "scaled_tangent_denominator": display(denominator),
            "denominator_sign": "strictly negative for all a,b,c>0",
            "conclusion": "tan(theta) is defined and equals numerator/denominator"
        }
    }, separators=(",", ":")))
else:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": {}},
                     separators=(",", ":")))
