import json
from fractions import Fraction
from math import isqrt
from itertools import combinations

def ceil_sqrt(n):
    r = isqrt(n)
    return r if r * r == n else r + 1

def witness(n):
    m = ceil_sqrt(n)
    return set(range(m)) | {(j * m) % n for j in range(1, m + 1)}

def covers_all_shifts(s, n):
    return len({(a - b) % n for a in s for b in s}) == n

def exact_minimum(n):
    # Translation preserves the property, so a minimum set may contain 0.
    for size in range(1, n + 1):
        for rest in combinations(range(1, n), size - 1):
            if covers_all_shifts((0,) + rest, n):
                return size
    raise ArithmeticError("No covering subset found")

def polynomial_product(a, b):
    result = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            result[i + j] += x * y
    return result

def degree(p):
    return max(i for i, coefficient in enumerate(p) if coefficient)

try:
    # A set of size s supplies at most s^2 ordered differences.
    ordered_pair_polynomial = polynomial_product([0, 1], [0, 1])
    lower_exponent = Fraction(1, degree(ordered_pair_polynomial))

    # The construction uses at most 2m elements, with m = ceil(sqrt(n)).
    size_bound_polynomial = [0, 2]
    capacity_polynomial = polynomial_product([0, 1], [0, 1])
    upper_exponent = Fraction(
        degree(size_bound_polynomial), degree(capacity_polynomial)
    )

    checked = 256
    for n in range(1, checked + 1):
        s = witness(n)
        assert len(s) <= 2 * ceil_sqrt(n)
        assert covers_all_shifts(s, n)

    minima = {str(n): exact_minimum(n) for n in range(1, 11)}
    assert lower_exponent == upper_exponent
    answer = lower_exponent

    evidence = {
        "equivalence": "Every shift intersects S iff S-S equals Z_n.",
        "lower_bound": "n <= |S-S| <= |S|^2, hence f(n) >= sqrt(n).",
        "universal_construction": (
            "Let m=ceil(sqrt(n)); take residues of 0,...,m-1 and "
            "m,2m,...,m^2. For each 0<=k<n, put j=ceil(k/m) "
            "and r=jm-k. Then 0<=j<=m, 0<=r<m, and k=jm-r "
            "is a difference of two chosen residues."
        ),
        "upper_bound": "f(n) <= 2ceil(sqrt(n)) <= 4sqrt(n).",
        "squeeze": (
            f"For n>1: {answer} <= ln(f(n))/ln(n) "
            f"<= {answer} + ln(4)/ln(n); the added term tends to zero."
        ),
        "construction_checks": checked,
        "exact_small_minima": minima
    }
    print(json.dumps({"final_answer": str(answer), "evidence": evidence},
                     separators=(",", ":")))
except Exception:
    print("UNSUPPORTED")
