from itertools import product

# Each work is distinct: 3 French novels, 3 Russian novels,
# 2 French plays, and 1 Russian play.
works = ("FN", "FN", "FN", "RN", "RN", "RN", "FP", "FP", "RP")

valid = []
for chosen in product((0, 1), repeat=len(works)):
    counts = {kind: 0 for kind in ("FN", "RN", "FP", "RP")}
    for selected, kind in zip(chosen, works):
        counts[kind] += selected

    fn, rn, fp, rp = (counts[k] for k in ("FN", "RN", "FP", "RP"))
    if not 5 <= sum(chosen) <= 6:
        continue
    if fn + fp > 4:
        continue
    if not 3 <= fn + rn <= 4:
        continue
    if fn < rn:
        continue
    if fp == 2 and rp != 0:
        continue
    valid.append(counts)

options = {
    "A": lambda c: c["RN"] == 0 and c["FP"] + c["RP"] == 1,
    "B": lambda c: c["RN"] == 1 and c["FP"] == 2,
    "C": lambda c: c["FN"] == 2 and c["RP"] == 1,
    "D": lambda c: c["FN"] == 2 and c["FP"] + c["RP"] == 2,
    "E": lambda c: c["RN"] == 2 and c["FP"] + c["RP"] == 1,
}

print("Exhaustively checked all 512 subsets.")
print("Valid selections:", len(valid))
impossible = []
for letter, predicate in options.items():
    matches = [c for c in valid if predicate(c)]
    print(f"{letter}: {len(matches)} valid selections satisfy this option.")
    if matches:
        print("  Witness counts:", matches[0])
    else:
        impossible.append(letter)

submitted = "A**".rstrip("*")
print("Options that cannot be true:", ", ".join(impossible) or "none")
if len(impossible) != 1:
    print("CHECK UNKNOWN: the question does not have a unique exception.")
elif submitted == impossible[0]:
    print("CHECK PASS")
else:
    print("CHECK FAIL: expected", impossible[0], "but submitted", submitted)
