import json
from fractions import Fraction
from math import lcm

# z = exp(i*pi/18), so z^36 = 1 and z^12 - z^6 + 1 = 0.
N = 12

def constant(value):
    return [Fraction(value)] + [Fraction(0)] * (N - 1)

def add(a, b):
    return [x + y for x, y in zip(a, b)]

def scale(a, value):
    return [x * value for x in a]

def multiply(a, b):
    coefficients = [Fraction(0)] * (2 * N - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            coefficients[i + j] += x * y
    for k in range(len(coefficients) - 1, N - 1, -1):
        value = coefficients[k]
        coefficients[k] = 0
        coefficients[k - 6] += value
        coefficients[k - 12] -= value
    return coefficients[:N]

def power(a, exponent):
    result = constant(1)
    while exponent:
        if exponent & 1:
            result = multiply(result, a)
        a = multiply(a, a)
        exponent //= 2
    return result

z = constant(0)
z[1] = Fraction(1)

def z_power(k):
    return power(z, k % 36)

def cosine(k):
    return scale(add(z_power(k), z_power(-k)), Fraction(1, 2))

def sine(k):
    # i = z^9, hence 1/i = -z^9.
    difference = add(z_power(k), scale(z_power(-k), -1))
    return scale(multiply(difference, z_power(9)), Fraction(-1, 2))

cos_product = constant(1)
sin_product = constant(1)
for k in (1, 5, 7):
    cos_product = multiply(cos_product, cosine(k))
    sin_product = multiply(sin_product, sine(k))

result = add(scale(cos_product, 6), sin_product)
root_three = add(z_power(3), z_power(-3))

def decompose(value):
    # Recover a and b from value = a + b*root_three.
    j = next(i for i in range(1, N) if root_three[i])
    b = value[j] / root_three[j]
    a = value[0] - b * root_three[0]
    if value != add(constant(a), scale(root_three, b)):
        raise ValueError("Exact decomposition failed")
    return a, b

