import json
import math

modulus = 4
square_residues = sorted({x * x % modulus for x in range(modulus)})

threshold = 0
factorial_value = 1
while factorial_value % modulus != 0:
    threshold += 1
    factorial_value *= threshold

# For every n >= threshold, n! is divisible by modulus.
# Since 21 == 1 (mod modulus), the remaining residue is constant.
if 21 % modulus != 1:
    print(json.dumps({"final_answer": "UNSUPPORTED"}))
else:
    tail_residue = (17 + 5) % modulus
    if tail_residue in square_residues:
        print(json.dumps({"final_answer": "UNSUPPORTED"}))
    else:
        checks = []
        solutions = []
        for n in range(threshold):
            value = (n**3 + 39*n - 2) * math.factorial(n) + 17 * 21**n + 5
            root = math.isqrt(value)
            is_square = root * root == value
            checks.append({
                "n": n,
                "value": value,
                "is_square": is_square
            })
            if is_square:
                solutions.append(n)

        answer = (
            "n = " + ", ".join(map(str, solutions))
            if solutions else "No natural numbers satisfy the condition."
        )
        print(json.dumps({
            "final_answer": answer,
            "evidence": {
                "finite_checks": checks,
                "all_larger_n_excluded": {
                    "n_ge": threshold,
                    "modulus": modulus,
                    "factorial_residue": 0,
                    "power_base_residue": 21 % modulus,
                    "expression_residue": tail_residue,
                    "square_residues": square_residues
                },
                "domain_note": "0 was also checked; excluding it does not change the result."
            }
        }, separators=(",", ":")))
