import json
from fractions import Fraction

# Each equation is (squared variable, linear variable, coefficient, RHS).
equations = [
    (0, 1, Fraction(-2), Fraction(-13)),
    (1, 2, Fraction(-4), Fraction(14)),
    (2, 0, Fraction(6), Fraction(-15)),
]

linear = [Fraction(0) for _ in range(3)]
rhs_sum = Fraction(0)
for squared, variable, coefficient, rhs in equations:
    linear[variable] += coefficient
    rhs_sum += rhs

center = [-coefficient / 2 for coefficient in linear]
radius_squared = rhs_sum + sum(value * value for value in center)

def exact(value):
    return str(value)

if radius_squared == 0:
    residuals = [
        center[squared] ** 2 + coefficient * center[variable] - rhs
        for squared, variable, coefficient, rhs in equations
    ]
    if all(value == 0 for value in residuals):
        x, y, z = center
        answer = exact(x * y + x * z + 6 * y * z)
        evidence = {"unique_real_solution": list(map(exact, center))}
    else:
        answer = "UNSUPPORTED"
        evidence = {
            "sum_of_completed_squares": exact(radius_squared),
            "only_possible_real_solution": list(map(exact, center)),
            "original_equation_residuals": list(map(exact, residuals)),
            "conclusion": "No real solution; the requested value is undefined."
        }
else:
    answer = "UNSUPPORTED"
    evidence = {"completed_square_rhs": exact(radius_squared)}

print(json.dumps({"final_answer": answer, "evidence": evidence},
                 separators=(",", ":")))
