import json
from fractions import Fraction
from math import factorial

# log(1+a*x)/(a*x) = sum_{k>=0} (-1)^k*a^k*x^k/(k+1).
# Terms through degree 1 suffice; the omitted terms are O(x^2).
def normalized_exp_coefficients(a):
    log_coefficients = [
        Fraction((-1) ** k * a ** k, k + 1) for k in range(2)
    ]
    assert log_coefficients[0] == 1

    # exp(c*x + O(x^2)) = 1 + c*x + O(x^2).
    exponential_coefficients = [
        log_coefficients[1] ** k / factorial(k) for k in range(2)
    ]
    return log_coefficients, exponential_coefficients

log1, exp1 = normalized_exp_coefficients(1)
log2, exp2 = normalized_exp_coefficients(2)

assert exp1[0] - exp2[0] == 0
coefficient = exp1[1] - exp2[1]

def times_e(q):
    if q == 0:
        return "0"
    sign = "-" if q < 0 else ""
    q = abs(q)
    numerator = "e" if q.numerator == 1 else f"{q.numerator}*e"
    return sign + numerator + (f"/{q.denominator}" if q.denominator != 1 else "")

print(json.dumps({
    "final_answer": times_e(coefficient),
    "evidence": {
        "real_domain_near_zero": "0 < |x| < 1/2",
        "log_exponent_coefficients_constant_and_linear": {
            "a=1": [str(v) for v in log1],
            "a=2": [str(v) for v in log2]
        },
        "numerator": f"e*({coefficient})*x + O(x^2)",
        "justification": "The convergent logarithm and exponential series give these expansions on both sides of zero; dividing by x leaves the computed linear coefficient times e."
    }
}, separators=(",", ":")))
```

