from collections import deque
from itertools import combinations

# Buildings: name, class. Class values are in units of one class-3 building.
buildings = [
    ("Garza Tower", 1),
    ("Yates House", 3),
    ("Zimmer House", 3),
    ("Flores Tower", 1),
    ("Lynch Building", 2),
    ("King Building", 2),
    ("Meyer Building", 2),
    ("Ortiz Building", 2),
]
companies = ("RealProp", "Southco", "Trustcorp")
index = {name: i for i, (name, _) in enumerate(buildings)}

def mask(names):
    return sum(1 << index[name] for name in names)

initial = (
    mask(["Garza Tower", "Yates House", "Zimmer House"]),
    mask(["Flores Tower", "Lynch Building"]),
    mask(["King Building", "Meyer Building", "Ortiz Building"]),
)

by_class = {
    c: [1 << i for i, (_, cls) in enumerate(buildings) if cls == c]
    for c in (1, 2, 3)
}

# Every legal exchange, represented by its two bundles.
trades = []
for cls in (1, 2, 3):
    trades.extend(combinations(by_class[cls], 2))
for first_class, second_class in ((1, 2), (2, 3)):
    for single in by_class[first_class]:
        for a, b in combinations(by_class[second_class], 2):
            trades.append((single, a | b))

# Include both directions of every exchange.
directed_trades = trades + [(b, a) for a, b in trades]

# Exhaustive search of the finite ownership-state graph.
seen = {initial}
queue = deque([initial])
while queue:
    state = queue.popleft()
    for i, j in combinations(range(3), 2):
        for give_i, give_j in directed_trades:
