from fractions import Fraction as F

breakpoints = sorted([F(-23), F(5), F(48)])

def height(x):
    return abs(x + 23) + abs(x - 5) + abs(x - 48) - 2*x

bounds = [None] + breakpoints + [None]
segments = []
for lo, hi in zip(bounds, bounds[1:]):
    sample = hi - 1 if lo is None else lo + 1 if hi is None else (lo + hi)/2
    signs = [F(1) if sample > b else F(-1) for b in breakpoints]
    slope = sum(signs) - 2
    intercept = -sum(s*b for s, b in zip(signs, breakpoints))
