from fractions import Fraction

# Exact polynomials in n and d, represented by {(n_power, d_power): coefficient}.
def add(a, b):
    result = dict(a)
    for key, value in b.items():
        result[key] = result.get(key, Fraction(0)) + value
    return {key: value for key, value in result.items() if value}

def scale(a, c):
    return {key: c * value for key, value in a.items() if c * value}

def mul(a, b):
    result = {}
    for (i, j), x in a.items():
        for (k, l), y in b.items():
            key = (i + k, j + l)
            result[key] = result.get(key, Fraction(0)) + x * y
    return {key: value for key, value in result.items() if value}

one = {(0, 0): Fraction(1)}
d = {(0, 1): Fraction(1)}
nd = {(1, 1): Fraction(1)}

# Verify the induction inequality:
# (1 + n*d) - (1-d)*(1 + (n+1)*d) = (n+1)*d^2 >= 0.
defect = add(
    add(one, nd),
    scale(mul(add(one, scale(d, -1)), add(add(one, nd), d)), -1)
)
expected = {(0, 2): Fraction(1), (1, 2): Fraction(1)}
if defect != expected:
    print("CHECK UNKNOWN")
    raise SystemExit

# For 0 < d <= 1, induction therefore gives
# (1-d)^n <= 1/(1+n*d).
# Apply with a = pi/2-epsilon, q = sin(a) = cos(epsilon), d = 1-q.
print("Assumption: epsilon is fixed and 0 < epsilon < pi/2.")
print("Let a = pi/2-epsilon and d = 1-cos(epsilon), so a > 0 and 0 < d < 1.")
print("On [0,a], 0 <= sin(x) <= 1-d and 1-sin(x) >= d.")
print("Exact induction certificate: (1+n*d)-(1-d)*(1+(n+1)*d) = (n+1)*d^2.")
print("Consequently, 0 <= integral <= a*(1-d)^n/d <= a/[d*(1+n*d)].")
print("For every eta > 0, any integer n > a/(eta*d^2) makes this bound < eta.")
print("Expected limit: 0")
print("Submitted answer: 0")
print("CHECK PASS")
