import itertools
import json

bands = ("U", "V", "W", "X", "Y", "Z")
original = set()
alternatives = {letter: set() for letter in "ABCDE"}

for order in itertools.permutations(bands):
    p = {band: slot for slot, band in enumerate(order, 1)}

    # Constraints retained under every proposed substitution.
    if not (p["V"] < p["Z"] and p["U"] >= 4 and p["Y"] <= 3):
        continue

    if p["W"] < p["X"] and p["Z"] < p["X"]:
        original.add(order)

    rules = {
        "A": all(p[b] < p["X"] for b in bands if b not in ("U", "X")),
        "B": p["V"] < p["W"] < p["Z"],
        "C": p["V"] < p["X"] and p["W"] < p["X"],
        "D": abs(p["X"] - p["U"]) == 1,
        "E": p["X"] in (5, 6),
    }
    for letter, holds in rules.items():
        if holds:
            alternatives[letter].add(order)

matches = [letter for letter, orders in alternatives.items()
           if orders == original]

evidence = {
    "original_count": len(original),
    "substitutions": {
        letter: {
            "count": len(orders),
            "added": len(orders - original),
            "removed": len(original - orders),
        }
        for letter, orders in alternatives.items()
    },
}

print(json.dumps({
    "final_answer": matches[0] if len(matches) == 1 else "UNSUPPORTED",
    "evidence": evidence,
}, separators=(",", ":")))
