        continue

    # Exactly two compositions occur after F but before O.
    if pos["O"] - pos["F"] != 3:
        continue

    valid.append(order)

r_positions = sorted({order.index("R") + 1 for order in valid})
options = {"A": 1, "B": 3, "C": 4, "D": 6, "E": 7}
