import itertools
import json

# The plan needs competent personnel, adequate funding, and participation.
# It does not require every student offered work to be impoverished:
# helping the impoverished subgroup is compatible with helping others too.
dimensions = (
    "all_students_impoverished",
    "competent_for_security",
    "funding_sufficient_for_scope",
    "participation_unimpeded",
)

worlds = [
    dict(zip(dimensions, values))
    for values in itertools.product((False, True), repeat=len(dimensions))
]

required = dimensions[1:]

# Each option identifies the feature it challenges.
claims = {
    "A": ("all_students_impoverished", False),
    "B": ("competent_for_security", False),
    "C": ("funding_sufficient_for_scope", False),
    "D": ("participation_unimpeded", False),
}

results = {}
for option, (feature, value) in claims.items():
    compatible = [w for w in worlds if w[feature] == value]
    successful = [
        w for w in compatible
        if all(w[requirement] for requirement in required)
    ]
    results[option] = {
        "successful_models": len(successful),
        "challenges_required_feature": feature in required,
    }

answers = [
    option for option, result in results.items()
    if result["successful_models"] > 0
    and not result["challenges_required_feature"]
]

print(json.dumps({
    "final_answer": answers[0] if len(answers) == 1 else "UNSUPPORTED",
    "evidence": {
        "enumeration": results,
        "reason": (
            "The plan can assist impoverished students without requiring "
            "all participating students to be impoverished. Competence, "
            "funding, and competing classes concern its practical implementation."
        ),
    },
}, separators=(",", ":")))
