# examples impose no precedence constraints.
pattern_examples = [
    (1, ("material", "origin")),       # cardboard egyptian
    (3, ("age", "purpose")),           # new snorkeling
    (27, ("size", "color")),           # little white
    (28, ("opinion", "shape")),        # good circular
    (167, ("opinion", "color", "age")), # silly aqua new
    (177, ("shape", "size", "purpose")) # square large walking
]

categories = (
    "opinion", "size", "age", "shape",
    "color", "origin", "material", "purpose"
)

vocabulary = {
    "opinion": "terrible good ridiculous nice",
    "size": "little large huge tiny medium-size big midsize small",
    "age": "ancient archaic old-fashioned old new",
    "shape": "circular square prismlike spherical",
    "color": "teal black magenta red violet cyan white yellow pink",
    "origin": "brazilian mexican turkish thai ethiopian nigerian",
    "material": "plastic wool wood paper steel leather",
    "purpose": "snorkeling drinking exercise walking whittling driving eating typing",
}
category_of = {
    word: category
    for category, words in vocabulary.items()
    for word in words.split()
}

options = {
    "A": "plastic little teal ancient snorkeling circular terrible",
    "B": "good square large black archaic drinking",
    "C": "ridiculous circular huge magenta ancient exercise brazilian wool",
    "D": "circular tiny red old-fashioned walking wood mexican",
    "E": "medium-size violet archaic whittling paper turkish",
    "F": "thai steel medium-size cyan archaic driving",
    "G": "turkish big white old drinking prismlike nice",
    "H": "midsize yellow new eating turkish wool",
    "I": "plastic ethiopian big black archaic snorkeling",
    "J": "nigerian leather small pink ancient typing spherical ridiculous",
}
option_categories = {
    letter: tuple(category_of[word] for word in words.split())
    for letter, words in options.items()
}

constraints = set()
for _, sequence in pattern_examples:
    constraints.update(itertools.combinations(sequence, 2))

outcomes = {}
valid_order_count = 0
for order in itertools.permutations(categories):
    position = {category: i for i, category in enumerate(order)}
    if not all(position[a] < position[b] for a, b in constraints):
        continue
    valid_order_count += 1
    answer = "".join(
        letter
        for letter, sequence in option_categories.items()
        if all(
            position[a] < position[b]
            for a, b in zip(sequence, sequence[1:])
        )
    ) or "K"
    if answer not in outcomes:
