    ("color age material", [204]),
]

edges = set()
for sequence, indices in given_groups:
    sequence = sequence.split()
    for i, left in enumerate(sequence):
        for right in sequence[i + 1:]:
            edges.add((left, right))

options = {
    "A": "huge archaic pakistani triangular steel maroon hiking",
    "B": "terrible tiny archaic indian rectangular iron black smoking",
    "C": "good small ancient pakistani square cloth pink",
