import itertools
import json

# Two employees suffice: John and a possible existential witness.
# Any relevant model can be reduced to these employees.
states = list(itertools.product((False, True), repeat=4))
model_count = 0
countermodels = []

for john, other in itertools.product(states, repeat=2):
    employees = (john, other)  # State order: seminars, skills, activities, teamwork

    rules_hold = all(
        (not seminars or skills) and (not activities or teamwork)
        for seminars, skills, activities, teamwork in employees
    )
    witness_exists = any(
        not skills and not teamwork
        for seminars, skills, activities, teamwork in employees
    )

    if rules_hold and witness_exists:
        model_count += 1
        conclusion = not john[0] or not john[2]
        if not conclusion:
            countermodels.append((john, other))

if model_count == 0:
    print("UNSUPPORTED")
else:
    evidence = {"models_checked": model_count,
                "countermodels": len(countermodels)}
    if countermodels:
        fields = ("attends_seminars", "enhances_skills",
                  "participates_in_activities", "fosters_teamwork")
        john, other = countermodels[0]
        evidence["counterexample"] = {
            "John": dict(zip(fields, john)),
            "other_employee": dict(zip(fields, other))
        }
    print(json.dumps({
        "final_answer": "no" if countermodels else "yes",
        "evidence": evidence
    }, separators=(",", ":")))
