import itertools
import json

events = ("long-distance running", "sprint", "high jump", "long jump", "shot put")
options = {
    "A": ("sprint", "shot put"),
    "B": ("sprint", "long jump"),
    "C": ("shot put", "high jump"),
    "D": ("long-distance running", "high jump"),
}

feasible = []
for size in (1, 2):
    for selection in itertools.combinations(events, size):
        chosen = set(selection)
        if "long-distance running" not in chosen:
            continue
        if chosen & {"sprint", "high jump", "long jump"}:
            continue
        if "long jump" in chosen and chosen & {"long-distance running", "shot put"}:
            continue
        feasible.append(selection)

# Each option uses "or": it is possible if at least one listed event
# occurs in an admissible selection for the long-distance-running grade.
possible = {
    label: any(set(selection).intersection(pair) for selection in feasible)
    for label, pair in options.items()
}
impossible = [label for label, value in possible.items() if not value]

print(json.dumps({
    "final_answer": impossible[0] if len(impossible) == 1 else "UNSUPPORTED",
    "evidence": {
        "feasible_selections": feasible,
        "option_possible": possible,
        "reason": "Running excludes sprint; long jump also explicitly excludes running. "
                  "Thus neither alternative in B is available, regardless of grade counts."
    }
}, separators=(",", ":")))
