# Ordinal hormone levels: only their ordering matters, not their magnitude.
# The given causal contrast is: feeling unloved yields less secretion.
hormone_responses = [
    (unloved, loved)
    for unloved, loved in itertools.product(range(3), repeat=2)
    if unloved < loved
]

# Each child's attributes:
# wants_taller, often_hugged, parent_loves, feels_loved, is_tall.
# Keep parental love distinct from the child's psychological feeling.
attributes = ("wants_taller", "often_hugged", "parent_loves",
              "feels_loved", "is_tall")
children = [
    dict(zip(attributes, bits))
    for bits in itertools.product((False, True), repeat=len(attributes))
    # Explicit antecedent: wanting taller children requires frequent hugs.
    if not bits[0] or bits[1]
]

counts = {letter: 0 for letter in "ABCD"}
counterexamples = {}
total = 0

for hormone_unloved, hormone_loved in hormone_responses:
    for first, second in itertools.product(children, repeat=2):
        # No given rule establishes that hugs themselves promote height.
        for hugs_promote_height in (False, True):
            pair = (first, second)

            # D compares taller and shorter children, not parental intentions.
            taller_pairs = [
                (x, y) for x, y in itertools.permutations(pair, 2)
                if x["is_tall"] and not y["is_tall"]
            ]

            claims = {
                "A": hugs_promote_height,
                "B": all(c["often_hugged"] or not c["parent_loves"]
                         for c in pair),
                # A change in psychological state changes a physical response.
                "C": hormone_unloved != hormone_loved,
                "D": all(int(x["often_hugged"]) > int(y["often_hugged"])
                         for x, y in taller_pairs),
            }

            total += 1
            for letter, holds in claims.items():
                counts[letter] += int(holds)
                if not holds and letter not in counterexamples:
                    counterexamples[letter] = {
                        "children": pair,
                        "hugs_promote_height": hugs_promote_height,
                    }

entailed = [letter for letter in counts if counts[letter] == total]
answer = entailed[0] if len(entailed) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "models_checked": total,
        "models_satisfying_each_option": counts,
        "causal_contrast": "unloved hormone level < loved hormone level",
        "interpretation": (
            "Feeling loved is psychological; hormone secretion is physical. "
            "The givens do not identify parental love with hugging, establish "
            "that hugs suffice for height growth, or compare tall and short "
            "children's hugging frequencies."
        )
    }
}, separators=(",", ":")))
