# Explicit facts; the football is not a basketball.
facts = {
    ("card_starts_v", True): "violet".startswith("v"),
    ("took_bike", True): True,
    ("movie_after_birth", True): 1926 > 1972,
}
money = {"dolphin": 49}
facts[("more_money", True)] = (
    "monkey" in money and money["dolphin"] > money["monkey"]
)

basketballs = []
box = tuple(map(Fraction, ("28.7", "24.9", "26.8")))
facts[("basketball_fits", True)] = any(
    all(2 * radius <= dimension for dimension in box)
    for radius in basketballs
)
base = {literal for literal, holds in facts.items() if holds}

trade = ("trades", True)
not_trade = ("trades", False)
not_shout = ("shouts", False)
borrow = ("borrows", True)

rules = {
    1: ({("card_starts_v", True)}, trade),
    2: ({("more_money", True)}, not_trade),
    3: ({not_shout, not_trade}, borrow),
    4: ({("movie_after_birth", True)}, trade),
    5: ({("took_bike", True)}, not_trade),
    6: ({("basketball_fits", True)}, not_shout),
}
preferred = {(1, 2), (1, 5), (4, 2), (4, 5)}

# Exhaustively check every possible set of derived literals.
heads = sorted({head for _, head in rules.values()})
models = []
for bits in product((False, True), repeat=len(heads)):
    derived = {head for head, present in zip(heads, bits) if present}
    applicable = {
        number
        for number, (body, _) in rules.items()
        if body <= base | derived
    }
    defeated = {
        number
        for number in applicable
        if any(
            (other, number) in preferred
            and rules[other][1]
            == (rules[number][1][0], not rules[number][1][1])
            for other in applicable
        )
    }
    accepted = applicable - defeated
    if derived == {rules[number][1] for number in accepted}:
        models.append((derived, applicable, defeated, accepted))

if len(models) != 1:
    print("UNSUPPORTED")
else:
    derived, applicable, defeated, accepted = models[0]
    positive = borrow in derived
    negative = ("borrows", False) in derived
    answer = (
        "proved" if positive and not negative
        else "disproved" if negative and not positive
        else "unknown"
    )
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "applicable_rules": sorted(applicable),
            "defeated_rules": sorted(defeated),
            "accepted_rules": sorted(accepted),
            "basketball_present": bool(basketballs),
            "borrow_supported": positive,
            "borrow_negation_supported": negative
        }
    }, separators=(",", ":")))
