# Propositions distinguish general tendencies from claims about particular works.
names = (
    "short_term_subjective",
    "contemporary_evaluations_often_diverge",
    "objective_contemporary_assessment_difficult",
    "davinci_bach_evaluations_differed_while_alive",
    "evaluations_differ_greatly_between_eras",
    "contemporary_critics_unanimous",
    "contemporary_work_great",
    "centuries_of_pleasure_and_beauty",
    "enduring_work_objectively_great",
)

def premises(m):
    return (
        m["short_term_subjective"]
        and m["contemporary_evaluations_often_diverge"]
        # Semantic unpacking: subjective assessment makes an objective
        # determination difficult, not necessarily impossible.
        and (
            not m["short_term_subjective"]
            or m["objective_contemporary_assessment_difficult"]
        )
        and (
            not m["centuries_of_pleasure_and_beauty"]
            or m["enduring_work_objectively_great"]
        )
    )

options = {
    "A": lambda m: m["davinci_bach_evaluations_differed_while_alive"],
    "B": lambda m: m["objective_contemporary_assessment_difficult"],
    "C": lambda m: m["evaluations_differ_greatly_between_eras"],
    "D": lambda m: (
        not m["contemporary_critics_unanimous"]
        or m["contemporary_work_great"]
    ),
}

models = [
    dict(zip(names, values))
    for values in itertools.product((False, True), repeat=len(names))
    if premises(dict(zip(names, values)))
]
countermodels = {
    option: sum(not test(model) for model in models)
    for option, test in options.items()
}
entailed = [option for option, count in countermodels.items() if count == 0]

print(json.dumps({
    "final_answer": entailed[0] if models and len(entailed) == 1 else "UNSUPPORTED",
    "evidence": {
        "admissible_models": len(models),
        "countermodels": countermodels,
        "interpretation": (
            "Short-term subjectivity supports difficulty objectively assessing "
            "contemporary art; it does not establish specific historical "
            "disagreement, cross-era disagreement, or greatness from unanimity."
        )
    }
}, separators=(",", ":")))
