from itertools import product

# Interpret "Have you quit drinking?" as presupposing that the addressee
# has drunk alcohol before. Test compatibility, not whether the reply
# directly answers the question.
models = []
for ever, now, trying, likes in product((False, True), repeat=4):
    if now and not ever:
        continue
    if trying and not ever:
        continue
    models.append({
        "ever": ever, "now": now, "trying": trying, "likes": likes
    })

options = {
    "A": ("I'm trying to quit drinking.", lambda m: m["trying"]),
    "B": ("I don't drink anymore.", lambda m: m["ever"] and not m["now"]),
    "C": ("I never drink.", lambda m: not m["ever"]),
    # Liking alcohol does not logically require actually drinking it.
    "D": ("I especially like drinking.", lambda m: m["likes"]),
}

compatible = []
for letter, (text, predicate) in options.items():
    replies = [m for m in models if predicate(m)]
    witnesses = [m for m in replies if m["ever"]]
    if witnesses:
        compatible.append(letter)
    print(f"{letter}. {text}")
    print(f"  Reply models: {len(replies)}; "
          f"models satisfying the presupposition: {len(witnesses)}")

print("Options compatible with the presupposition:", ", ".join(compatible))
print("Submitted D is compatible:", "D" in compatible)
if compatible == ["D"]:
    print("CHECK PASS")
elif "D" not in compatible:
    print("CHECK FAIL")
else:
    print("UNSUPPORTED: the wording does not establish D as the unique answer.")
    print("CHECK UNKNOWN")
