import json
from fractions import Fraction

# P: a+b > 4; Q: a > 2 and b > 2.
coefficients = (Fraction(1), Fraction(1))
q_lower_bounds = (Fraction(2), Fraction(2))
p_threshold = Fraction(4)

# Positive coefficients preserve the strict lower bounds in Q.
sum_lower_bound = sum(
    c * bound for c, bound in zip(coefficients, q_lower_bounds)
)
necessary = (
    all(c > 0 for c in coefficients)
    and sum_lower_bound >= p_threshold
)

# One exact counterexample settles whether P implies Q.
counterexample = next(
    (
        (a, b)
        for a in range(7)
        for b in range(7)
        if a + b > p_threshold and not (a > 2 and b > 2)
    ),
    None,
)

if not necessary or counterexample is None:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": {}}))
else:
    sufficient = False
    answers = {
        (True, False): "A: Sufficient but not necessary condition",
        (False, True): "B: Necessary but not sufficient condition",
        (True, True): "C: Necessary and sufficient condition",
        (False, False): "D: Neither necessary nor sufficient condition",
    }
    a, b = counterexample
    print(json.dumps({
        "final_answer": answers[(sufficient, necessary)],
        "evidence": {
            "Q_implies_P": {
                "strict_sum_lower_bound": str(sum_lower_bound),
                "required_threshold": str(p_threshold)
            },
            "P_does_not_imply_Q": {
                "a": a, "b": b, "sum": a + b,
                "P": a + b > p_threshold,
                "Q": a > 2 and b > 2
            }
        }
    }, separators=(",", ":")))
