import itertools
import json
from math import gcd
from functools import reduce

def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def cross(a, b):
    return (a[1]*b[2] - a[2]*b[1],
            a[2]*b[0] - a[0]*b[2],
            a[0]*b[1] - a[1]*b[0])

def canonical(v):
    g = reduce(gcd, (abs(x) for x in v), 0)
    if not g:
        return None
    v = tuple(x // g for x in v)
    return tuple(-x for x in v) if next(x for x in v if x) < 0 else v

directions = sorted({
    canonical(v)
    for v in itertools.product((-1, 0, 1), repeat=3)
    if any(v)
})

def counterexample(label):
    for a, b, g in itertools.permutations(directions, 3):
        if label == "A":
            if dot(a, b) != 0:
                continue
            ell = canonical(cross(a, b))
            candidates = [
                m for m in directions
                if dot(m, ell) == 0 and cross(m, b) != (0, 0, 0)
            ]
        elif label == "B":
            if dot(a, g) != 0 or dot(b, g) != 0:
                continue
            candidates = [canonical(cross(a, g))]
            ell = None
        else:
            if dot(a, g) != 0 or dot(b, g) != 0:
                continue
            candidates = [a]
            ell = None

