            if m is None or cross(m, b) == (0, 0, 0):
                continue
            l = ell or next(v for v in directions if v != m)
            if l == m:
                continue
            n = next(v for v in directions if v not in (m, l))
            return {
                "plane_normals": {"alpha": a, "beta": b, "gamma": g},
                "line_directions": {"m": m, "n": n, "l": l},
                "m_cross_beta_normal": cross(m, b),
                "placement": "All planes and lines pass through the origin."
            }
    return None

# Sparse exact polynomials in x,y,z,s,r,q.
ZERO = (0,) * 6

def variable(i):
