import itertools
import json

# Unary predicates:
# P: participates, S: strong, R: seldom sick, U: unwell.
# Premises: P -> S, S -> R, and exists x (U(x) and not P(x)).
types = [
    t for t in itertools.product((False, True), repeat=4)
    if (not t[0] or t[1]) and (not t[1] or t[2])
]

counterexamples = {}
model_count = 0

# For these unary formulas, multiplicities are irrelevant: every finite
# or infinite model is equivalent to a subset of the possible unary types.
for mask in range(1 << len(types)):
    model = [t for i, t in enumerate(types) if mask & (1 << i)]
    if not any(u and not p for p, s, r, u in model):
        continue

    model_count += 1
    conclusions = {
        "A": any(u and r for p, s, r, u in model),
        "C": any(r and u for p, s, r, u in model),
        "D": any(s and u for p, s, r, u in model),
    }

    for option, holds in conclusions.items():
        if not holds:
            old = counterexamples.get(option)
            if old is None or len(model) < len(old):
                counterexamples[option] = model

not_entailed = sorted(counterexamples)
# Multiple demonstrably non-entailed options prevent a unique answer,
# independently of how the vague phrase "very few" in B is interpreted.
answer = "UNSUPPORTED"
if len(not_entailed) < 2:
    reason = "The exact meaning of 'very few' in B is unspecified."
else:
    reason = "More than one option cannot be derived from the premises."

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "models_checked": model_count,
        "not_entailed": not_entailed,
        "counterexample_fields": ["participates", "strong", "seldom_sick", "unwell"],
        "counterexamples": counterexamples,
        "reason": reason
    }
}, separators=(",", ":")))
