import json

people = ("G", "H", "K", "L", "P", "S")
texts = {
    "A": "G and S are on duty on the same day",
    "B": "S and H are not on duty on the same day",
    "C": "K and S are not on duty on the same day",
    "D": "K and G are not on duty on the same day",
}
valid_count = 0
true_counts = dict.fromkeys(texts, 0)
counterexamples = {}

for days in itertools.product((1, 2, 3), repeat=6):
    if any(days.count(day) != 2 for day in (1, 2, 3)):
        continue
    d = dict(zip(people, days))
    if d["L"] != d["P"] or d["G"] == d["H"]:
        continue
    if d["K"] == 1 and d["G"] != 2:
        continue
    if d["S"] == 3 and d["H"] != 2:
        continue

    valid_count += 1
    statements = {
        "A": d["G"] == d["S"],
        "B": d["S"] != d["H"],
        "C": d["K"] != d["S"],
        "D": d["K"] != d["G"],
    }
    for option, holds in statements.items():
        true_counts[option] += int(holds)
        if not holds and option not in counterexamples:
            counterexamples[option] = [
                [p for p in people if d[p] == day]
                for day in (1, 2, 3)
            ]

