    for nxt in adj[last]:
        if nxt == start:
            if len(route) >= 3 and route[1] < route[-1]:
                inspect(route)
        elif nxt > start and nxt not in visited:
            visited.add(nxt)
            route.append(nxt)
            dfs(start, route, visited)
            route.pop()
            visited.remove(nxt)

