    "final_answer": answer,
    "evidence": {
        "method": "Exact enumeration of adjoining white squares in each next row",
        "boards": evidence,
        "issue": (
            "Endpoint columns and starting color are not specified; "
            "no listed option occurs for any fixed endpoints."
