# SpaceX was founded in 2002; the stated movie was released in 1990.
movie_year = 1990
spacex_founding_year = 2002

facts = {"bee_takes_over"}
if movie_year < spacex_founding_year:
    facts.add("movie_before_spacex")

# Unstated antecedents (matching liger name, seating, fitting notebook)
# are not assumed true.
rules = {
    "Rule1": ({"wall_destroyed"}, "plant"),
    "Rule2": ({"bee_takes_over"}, "wall_destroyed"),
    "Rule3": ({"bee_liger_initials_match"}, "not_wall_destroyed"),
    "Rule4": ({"movie_before_spacex"}, "not_swear"),
    "Rule5": ({"otter_has_seat"}, "not_swear"),
    "Rule6": ({"not_swear"}, "not_plant"),
    "Rule7": ({"otter_has_fitting_notebook"}, "swear"),
}
preferred = {
    ("Rule3", "Rule2"),
    ("Rule6", "Rule1"),
    ("Rule7", "Rule4"),
    ("Rule7", "Rule5"),
}
opposite = {
    "wall_destroyed": "not_wall_destroyed",
    "not_wall_destroyed": "wall_destroyed",
    "swear": "not_swear",
    "not_swear": "swear",
    "plant": "not_plant",
    "not_plant": "plant",
}

names = list(rules)
models = []

# Exhaustively find grounded, preference-respecting rule extensions.
for bits in product((False, True), repeat=len(names)):
    active = {name for name, bit in zip(names, bits) if bit}
    derived = set(facts)
    while True:
        enlarged = derived | {
            rules[name][1]
            for name in active
            if rules[name][0] <= derived
        }
        if enlarged == derived:
            break
        derived = enlarged

    applicable = {
        name for name, (body, _) in rules.items() if body <= derived
    }
    expected = {
        name for name in applicable
        if not any(
            (stronger, name) in preferred
            and rules[stronger][1] == opposite.get(rules[name][1])
            for stronger in active
        )
    }
    if active == expected:
        models.append((active, derived))

if not models:
    print("UNSUPPORTED")
else:
    outcomes = set()
    for _, derived in models:
        positive = "plant" in derived
        negative = "not_plant" in derived
        outcomes.add(
            "proved" if positive and not negative
            else "disproved" if negative and not positive
            else "unknown"
        )

    if len(outcomes) != 1:
        print("UNSUPPORTED")
    else:
        print(json.dumps({
            "final_answer": outcomes.pop(),
            "evidence": {
                "movie_precedes_spacex": movie_year < spacex_founding_year,
                "extensions": len(models),
                "active_rules": sorted(set.intersection(
                    *(active for active, _ in models)
                )),
                "overridden_rule": "Rule1",
                "decisive_preference": "Rule6 > Rule1"
            }
        }, separators=(",", ":")))
