import json

# A strict majority is a conservative finite interpretation of "most".
# We require a strict majority of animals to be BOTH furry and good pets,
# every cat to lack fur, and a strict majority of dogs not to be pets.
# A countermodel is sufficient to refute entailment.
countermodel = None

for n in range(3, 6):
    cats = 1 << 0
    dogs = 1 << 1
    universe = (1 << n) - 1

    for furry in range(1 << n):
        if furry & cats:
            continue
        for pets in range(1 << n):
            typical = (furry & pets).bit_count()
            nonpet_dogs = (dogs & (universe ^ pets)).bit_count()

            premises = (
                2 * typical > n
                and 2 * nonpet_dogs > dogs.bit_count()
            )
            query = (
                (dogs & furry) == dogs
                and (cats & pets) == cats
            )

            if premises and not query:
                countermodel = {
                    "animals": [
                        {
                            "kind": "cat" if i == 0 else
                                    "dog" if i == 1 else "other",
                            "furry": bool(furry & (1 << i)),
                            "pet": bool(pets & (1 << i))
                        }
                        for i in range(n)
                    ],
                    "furry_and_pet_count": typical,
                    "total_animals": n,
                    "premises_satisfied": premises,
                    "queried_conjunction": query
                }
                break
        if countermodel is not None:
            break
    if countermodel is not None:
        break

print(json.dumps({
    "final_answer": "no" if countermodel is not None else "UNSUPPORTED",
    "evidence": countermodel
}, separators=(",", ":")))
